#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> h(n);
    for (int i = 0; i < n; ++i) {
        cin >> h[i];
    }

    vector<int> left_max(n);
    left_max[0] = h[0];
    for (int i = 1; i < n; ++i) {
        left_max[i] = max(left_max[i - 1], h[i]);
    }

    vector<int> right_max(n);
    right_max[n - 1] = h[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        right_max[i] = max(right_max[i + 1], h[i]);
    }

    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (min(left_max[i], right_max[i]) > h[i]) {
            count++;
        }
    }

    cout << count << "\n";

    return 0;
}
